// LEAD ONLY: navigation, layout and shared wiring. Team members: do not edit this file; ask the lead.
import { useEffect, useState } from "react";
import { Route, Routes } from "react-router-dom";
import Navbar from "./components/Navbar";
import Dashboard from "./Dashboard";
import WeatherPage from "./WeatherPage";
import Crops from "./Crops";
import Farms from "./Farms";
import Auth from "./Auth";
import { t } from "./i18n";
import { API_BASE, api, pending } from "./api";

function ConnectionBanner() {
  const [down, setDown] = useState(false);
  useEffect(() => { api.health().then(() => setDown(false)).catch(() => setDown(true)); }, []);
  return down ? <p className="banner" role="status">{t("apiOffline")} ({API_BASE})</p> : null;
}

function DemoBanner() {
  const [demo, setDemo] = useState(false);
  useEffect(() => { api.sources().then((l) => setDemo(l.some((s) => s.organisation.toUpperCase().startsWith("SAMPLE")))).catch(() => {}); }, []);
  return demo ? <p className="banner demo" role="alert">DEMO MODE: the planting calendar shows SAMPLE placeholder dates. They are not real agronomic data.</p> : null;
}

export default function App() {
  const [user, setUser] = useState(localStorage.getItem("name"));
  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("name");
    setUser(null);
  };
  return (
    <>
      <Navbar user={user} onLogout={logout} />
      <p className="banner">{t("disclaimer")}{pending() > 0 && ` · ${pending()} ${t("pending")}`}</p>
      <ConnectionBanner />
      <DemoBanner />
      <main>
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/weather" element={<WeatherPage />} />
          <Route path="/crops" element={<Crops />} />
          <Route path="/my-farm" element={user ? <Farms /> : <Auth onDone={setUser} />} />
          <Route path="*" element={<h2>Page not found</h2>} />
        </Routes>
      </main>
      <footer className="foot">Weather data by <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo.com</a>. For official advice see <a href="https://meteo.go.ke/Services/agrometeorology/" target="_blank" rel="noreferrer">KMD Agrometeorology</a>.</footer>
    </>
  );
}
